#[test]
fn native_source_checkpoint_status_records_portability_without_full_runtime_promotion() {
    let catalog = StatusCatalog::load(default_catalog_path()).unwrap();
    let cell = catalog
        .cells
        .iter()
        .find(|c| c.id == "leselang/language-vm/host-neutral-embedding")
        .unwrap();
    assert_eq!(cell.contract.version, "0.172.0");
    assert_eq!(cell.contract.stability, ContractStability::Draft);
    assert_eq!(cell.maturity, Maturity::Developing);
    assert_eq!(cell.lifecycle, Lifecycle::Target);
    assert_eq!(cell.completion, 10);
    for surface in [
        "native-source-checkpoint-from-unchanged-production-rust",
        "explicit-crate-metadata-and-locked-registry-closure",
        "native-all-features-with-no-enableable-product-profile",
        "standalone-workspace-and-separate-exported-consumer-ci",
        "bounded-exact-inventory-and-no-publication-on-proof-failure",
        "source-portability-not-complete-durable-vm-extraction",
    ] {
        assert!(cell.contract.surfaces.iter().any(|s| s == surface));
    }
    for path in [
        "crates/gewyvern-dev/src/leselang.rs",
        "crates/gewyvern-dev/src/main.rs",
        "crates/gewyvern-dev/src/version.rs",
        "tests/leselang_native_profile_tdd.rs",
        ".github/workflows/ci.yml",
        "docs/development.md",
    ] {
        assert!(
            cell.evidence
                .iter()
                .any(|e| e.path == path && e.state == EvidenceState::Present)
        );
    }
    for boundary in [
        "cargo dev package leselang --verify",
        "byte-for-byte",
        "original locked registry closure",
        "outside the monorepo",
        "failed proof, changed or unplanned files publish no checkpoint",
        "complete_vm/full_extraction_gate=false",
        "Product-coupled durable recovery and product migration remain",
    ] {
        assert!(
            cell.next_gate.contains(boundary),
            "source portability status lost {boundary}"
        );
    }
}

#[test]
fn native_vm_source_portability_keeps_complete_runtime_acceptance_open() {
    let catalog = StatusCatalog::load(default_catalog_path()).unwrap();
    let cell = catalog
        .cells
        .iter()
        .find(|cell| cell.id == "leselang/language-vm/host-neutral-embedding")
        .unwrap();
    assert_eq!(cell.contract.version, "0.172.0");
    assert_eq!(cell.maturity, Maturity::Developing);
    assert_eq!(cell.completion, 10);
    for surface in [
        "four-crate-native-vm-source-checkpoint",
        "closed-reference-vm-manifest-projection-with-no-enableable-product-storage-feature",
        "unchanged-native-vm-host-proof-in-independent-consumer",
        "native-vm-facade-inventory-bit-not-complete-runtime-promotion",
    ] {
        assert!(cell.contract.surfaces.iter().any(|s| s == surface));
    }
    let path = "docs/fixtures/leselang_native_vm_source_export_macos_arm64_20261012.json";
    assert!(
        cell.evidence
            .iter()
            .any(|e| e.path == path && e.state == EvidenceState::Present)
    );
    let proof: serde_json::Value =
        serde_json::from_str(&std::fs::read_to_string(repository_root().join(path)).unwrap())
            .unwrap();
    assert_eq!(proof["kind"], "leselang-native-vm-source-export");
    assert_eq!(
        proof["source_crates"],
        serde_json::json!([
            "leselang-syntax",
            "leselang-runtime-core",
            "leselang-hir",
            "leselang-vm"
        ])
    );
    for flag in [
        "verified",
        "native_vm_facade",
        "source_outside_product_workspace",
        "production_source_byte_for_byte",
        "consumer_native_vm_proof_unchanged",
    ] {
        assert_eq!(proof[flag], true);
    }
    for flag in [
        "complete_vm",
        "full_extraction_gate",
        "reference_features_enableable",
    ] {
        assert_eq!(proof[flag], false);
    }
    for result in [
        "workspace_all_features_tests",
        "workspace_strict_clippy",
        "independent_consumer_tests",
        "independent_consumer_strict_clippy",
    ] {
        assert_eq!(proof[result], "passed");
    }
    assert_eq!(proof["files"], 242);
    assert_eq!(proof["copied_files"], 232);
    assert_eq!(proof["bytes"], 4230415);
    assert_eq!(proof["reference_test_targets_omitted"], 51);
    assert_eq!(proof["reference_example_targets_omitted"], 1);
    assert_eq!(proof["native_vm_workspace_host_tests"], 9);
    assert_eq!(proof["native_vm_product_api_absence_doctests"], 1);
    assert_eq!(proof["independent_consumer_native_vm_host_tests"], 9);
    let hashes = proof["provenance"].as_array().unwrap();
    assert_eq!(hashes.len(), 4);
    assert_eq!(hashes[2]["source"], hashes[3]["source"]);
    assert_eq!(hashes[2]["sha256"], hashes[3]["sha256"]);
    for row in hashes {
        let hash = row["sha256"].as_str().unwrap();
        assert_eq!(hash.len(), 64);
        assert!(hash.bytes().all(|b| b.is_ascii_hexdigit()));
    }
    assert!(
        cell.next_gate
            .contains("four-crate native source checkpoint")
    );
    assert!(
        cell.next_gate
            .contains("this closes facade portability, not complete language/group coverage")
    );
}

#[test]
fn native_projection_export_retains_conditional_pipeline_evidence_without_full_vm_promotion() {
    let path = "docs/fixtures/leselang_native_projection_source_export_macos_arm64_20261013.json";
    let catalog = StatusCatalog::load(default_catalog_path()).unwrap();
    for id in [
        "leselang/language-hir/typed-effects",
        "leselang/language-vm/host-neutral-embedding",
    ] {
        let cell = catalog.cells.iter().find(|cell| cell.id == id).unwrap();
        assert!(
            cell.evidence.iter().any(|evidence| {
                evidence.path == path && evidence.state == EvidenceState::Present
            })
        );
    }
    let proof: serde_json::Value =
        serde_json::from_str(&std::fs::read_to_string(repository_root().join(path)).unwrap())
            .unwrap();
    assert_eq!(proof["kind"], "leselang-native-projection-source-export");
    assert_eq!(proof["platform"], "macos-arm64");
    assert_eq!(proof["validated_at"], "2026-10-13");
    for flag in [
        "verified",
        "native_vm_facade",
        "source_outside_product_workspace",
        "copied_source_byte_for_byte",
        "consumer_pipeline_proof_unchanged",
    ] {
        assert_eq!(proof[flag], true);
    }
    assert_eq!(proof["complete_vm"], false);
    assert_eq!(proof["full_extraction_gate"], false);
    for outcome in [
        "workspace_all_features_tests",
        "workspace_strict_clippy",
        "independent_consumer_tests",
        "independent_consumer_strict_clippy",
    ] {
        assert_eq!(proof[outcome], "passed");
    }
    assert_eq!(proof["files"], 250);
    assert_eq!(proof["copied_files"], 240);
    assert_eq!(proof["bytes"], 5_033_016);
    assert_eq!(proof["isolated_test_executions"], 2103);
    assert_eq!(proof["workspace_pipeline_tests"], 20);
    assert_eq!(proof["independent_consumer_pipeline_tests"], 20);
    assert_eq!(proof["conditional_host_program_paths"], 16);
    let rows = proof["provenance"].as_array().unwrap();
    assert_eq!(rows.len(), 4);
    assert_eq!(
        rows[2]["path"],
        "crates/leselang-vm/tests/native_host_pipeline.rs"
    );
    assert_eq!(rows[3]["path"], "consumer/tests/native_host_pipeline.rs");
    assert_eq!(rows[2]["source"], rows[3]["source"]);
    assert_eq!(rows[2]["sha256"], rows[3]["sha256"]);
    for hash in rows.iter().map(|row| &row["sha256"]).chain([
        &proof["export_manifest_sha256"],
        &proof["verification_log_sha256"],
    ]) {
        let hash = hash.as_str().unwrap();
        assert_eq!(hash.len(), 64);
        assert!(hash.bytes().all(|byte| byte.is_ascii_hexdigit()));
    }
    let docs =
        std::fs::read_to_string(repository_root().join("docs/leselang-embedding.md")).unwrap();
    assert!(docs.contains(path.strip_prefix("docs/").unwrap()));
    assert_eq!(proof["remaining_gates"].as_array().unwrap().len(), 4);
}

