#[test]
fn shared_native_foundations_cut_the_reverse_protocol_dependency() {
    let root = repository_root();
    let root_manifest =
        std::fs::read_to_string(root.join("Cargo.toml")).expect("workspace manifest must exist");
    let normal_dependencies = root_manifest
        .split_once("[dependencies]")
        .expect("root dependencies section must exist")
        .1
        .split_once("[dev-dependencies]")
        .expect("root dev-dependencies section must exist")
        .0;
    assert!(normal_dependencies.contains("gewyvern-install-contract"));
    assert!(normal_dependencies.contains("silvortex-bounded-io"));
    assert!(!normal_dependencies.contains("leserpent-protocol"));
    assert!(!normal_dependencies.contains("leserpent-domain"));

    let bounded_manifest =
        std::fs::read_to_string(root.join("crates/silvortex-bounded-io/Cargo.toml"))
            .expect("bounded I/O manifest must exist");
    let bounded_source =
        std::fs::read_to_string(root.join("crates/silvortex-bounded-io/src/lib.rs"))
            .expect("bounded I/O source must exist");
    for product in ["gewyvern", "leserpent", "leselang", "etragon"] {
        assert!(
            !bounded_manifest.to_ascii_lowercase().contains(product)
                && !bounded_source.to_ascii_lowercase().contains(product),
            "product-neutral bounded I/O leaked {product} semantics"
        );
    }

    let identity_manifest =
        std::fs::read_to_string(root.join("crates/silvortex-identity/Cargo.toml"))
            .expect("identity manifest must exist");
    let identity_source =
        std::fs::read_to_string(root.join("crates/silvortex-identity/src/lib.rs"))
            .expect("identity source must exist");
    for product in ["gewyvern", "leserpent", "leselang", "etragon"] {
        assert!(
            !identity_manifest.to_ascii_lowercase().contains(product)
                && !identity_source.to_ascii_lowercase().contains(product),
            "product-neutral identity crate leaked {product} semantics"
        );
    }

    let install_manifest =
        std::fs::read_to_string(root.join("crates/gewyvern-install-contract/Cargo.toml"))
            .expect("install contract manifest must exist");
    assert!(install_manifest.contains("silvortex-identity"));
    assert!(!install_manifest.contains("leserpent-domain"));

    let protocol = std::fs::read_to_string(root.join("crates/leserpent-protocol/src/lib.rs"))
        .expect("Leserpent protocol source must exist");
    assert!(protocol.contains("pub use silvortex_bounded_io as transport_safety"));
    assert!(
        protocol.contains("pub use gewyvern_install_contract::installer as gewyvern_installer")
    );
    assert!(
        protocol.contains("pub use gewyvern_install_contract::retirement as gewyvern_retirement")
    );

    let catalog = StatusCatalog::load(default_catalog_path()).expect("catalog must decode");
    let bounded = catalog
        .cells
        .iter()
        .find(|cell| cell.id == "shared-foundation/bounded-io/bounded-native-io")
        .expect("bounded I/O foundation must be tracked");
    assert!(bounded.depends_on.is_empty());
    assert_eq!(bounded.independence, Independence::ReusableLibrary);
    assert_eq!(bounded.contract.version, "1.2.0");
    assert!(
        bounded
            .contract
            .surfaces
            .contains(&"bounded-private-locked-append".to_string())
    );
    let machine_contract = catalog
        .cells
        .iter()
        .find(|cell| cell.id == "gewyvern-core/runtime-evidence/evidence-reconstruction")
        .expect("Gewyvern machine contract must be tracked");
    assert_eq!(machine_contract.contract.version, "1.10.0");
    for surface in [
        "bounded-private-stream-output",
        "bounded-private-validation-json-output",
    ] {
        assert!(
            machine_contract
                .contract
                .surfaces
                .contains(&surface.to_string())
        );
    }
    for path in ["src/serve_runtime.rs", "src/bin/gewyvern_validate.rs"] {
        assert!(
            machine_contract
                .evidence
                .iter()
                .any(|evidence| evidence.path == path && evidence.state == EvidenceState::Present)
        );
    }
    let identity = catalog
        .cells
        .iter()
        .find(|cell| cell.id == "shared-foundation/identity/validated-identities")
        .expect("validated identity foundation must be tracked");
    assert!(identity.depends_on.is_empty());
    assert!(identity.blockers.is_empty());
    assert_eq!(identity.independence, Independence::ReusableLibrary);
    let install = catalog
        .cells
        .iter()
        .find(|cell| cell.id == "shared-foundation/install-contract/gewyvern-install-wire")
        .expect("install contract foundation must be tracked");
    assert_eq!(install.independence, Independence::ReusableLibrary);
    assert!(install.blockers.is_empty());
    assert_eq!(
        install.depends_on,
        vec!["shared-foundation/identity/validated-identities"]
    );
}

#[test]
fn project_status_calibration_separates_delivery_from_the_full_portfolio() {
    let catalog = StatusCatalog::load(default_catalog_path()).expect("catalog must decode");
    let summary = catalog.summary(catalog.cells.len());

    assert_eq!(Priority::Critical.delivery_weight(), 4);
    assert_eq!(Priority::Active.delivery_weight(), 2);
    assert_eq!(Priority::Maintenance.delivery_weight(), 1);
    assert_eq!(Priority::Deferred.delivery_weight(), 0);

    let delivery_weight = catalog
        .cells
        .iter()
        .map(|cell| u64::from(cell.priority.delivery_weight()))
        .sum::<u64>();
    let expected_delivery_score = catalog
        .cells
        .iter()
        .map(|cell| {
            u64::from(catalog.cell_score(cell)) * u64::from(cell.priority.delivery_weight())
        })
        .sum::<u64>()
        / delivery_weight;
    let expected_delivery_completion = catalog
        .cells
        .iter()
        .map(|cell| u64::from(cell.completion) * u64::from(cell.priority.delivery_weight()))
        .sum::<u64>()
        / delivery_weight;
    let expected_portfolio_score = catalog
        .cells
        .iter()
        .map(|cell| u64::from(catalog.cell_score(cell)))
        .sum::<u64>()
        / catalog.cells.len() as u64;

    assert_eq!(u64::from(summary.overall_score), expected_delivery_score);
    assert_eq!(
        u64::from(summary.delivery_completion),
        expected_delivery_completion
    );
    assert_eq!(u64::from(summary.portfolio_score), expected_portfolio_score);
    assert_eq!(summary.deferred_cell_count, 2);
    assert_eq!(summary.deferred.len(), 2);
    assert_eq!(
        summary
            .deferred
            .iter()
            .map(|cell| cell.id.as_str())
            .collect::<BTreeSet<_>>(),
        BTreeSet::from([
            "etragon/learning-sidecar/advisory-learning",
            "leserpent-2/release-assurance/desktop-account-proof",
        ])
    );
    for attention_view in [
        &summary.weakest,
        &summary.in_development,
        &summary.independently_usable,
    ] {
        assert!(
            attention_view
                .iter()
                .all(|cell| cell.priority != Priority::Deferred)
        );
    }

    let governance = catalog
        .cells
        .iter()
        .find(|cell| cell.id == "project-governance/status-governance/status-tensor")
        .expect("status governance cell must exist");
    assert_eq!(governance.contract.version, "3.0.0");
    for surface in [
        "explicit-roadmap-priority",
        "priority-weighted-delivery-score",
        "equal-weight-portfolio-score",
        "deferred-attention-separation",
        "maturity-completion-coherence",
    ] {
        assert!(
            governance
                .contract
                .surfaces
                .iter()
                .any(|item| item == surface)
        );
    }
}

